import{H as e,ht as t,nt as n,tt as r}from"./chunks/framework.CXX_0q1Z.js";var i=JSON.parse(`{"title":"EmakiGem","description":"","frontmatter":{},"headers":[],"relativePath":"modules/gem/index.md","filePath":"modules/gem/index.md","lastUpdated":0}`),a={name:`modules/gem/index.md`};function o(e,i,a,o,s,c){return t(),r(`div`,null,[...i[0]||=[n(`<h1 id="emakigem" tabindex="-1">EmakiGem <a class="header-anchor" href="#emakigem" aria-label="Permalink to “EmakiGem”">​</a></h1><p>EmakiGem 是宝石与插槽模块，提供装备插槽、开孔器、宝石镶嵌、提取、升级、宝石共鸣与可选 Attribute 属性输出。它适合给装备添加长期养成和个性化搭配空间。</p><h2 id="基本信息" tabindex="-1">基本信息 <a class="header-anchor" href="#基本信息" aria-label="Permalink to “基本信息”">​</a></h2><table tabindex="0"><thead><tr><th>项目</th><th>值</th></tr></thead><tbody><tr><td>模块版本</td><td><code>2.8.0</code></td></tr><tr><td>主命令</td><td><code>/emakigem</code></td></tr><tr><td>别名</td><td><code>/egem</code>、<code>/eg</code></td></tr><tr><td>硬依赖</td><td>EmakiCoreLib</td></tr><tr><td>软依赖</td><td>EmakiItem、EmakiAttribute、PlaceholderAPI</td></tr><tr><td>主要权限</td><td><code>emakigem.use</code>、<code>emakigem.reload</code>、<code>emakigem.admin</code>、<code>emakigem.debug</code></td></tr></tbody></table><h2 id="核心概念" tabindex="-1">核心概念 <a class="header-anchor" href="#核心概念" aria-label="Permalink to “核心概念”">​</a></h2><table tabindex="0"><thead><tr><th>概念</th><th>说明</th></tr></thead><tbody><tr><td>插槽物品配置</td><td>定义某类装备允许拥有多少插槽、可镶嵌什么宝石。</td></tr><tr><td>插槽</td><td>装备上的宝石位置，有类型限制（attack/defense/utility/universal）。</td></tr><tr><td>开孔</td><td>解锁装备上未开放的插槽。</td></tr><tr><td>宝石</td><td>可镶嵌到插槽中的物品，提供属性、技能和外观效果。</td></tr><tr><td>提取</td><td>将已镶嵌宝石取出，可能消耗材料或有失败风险。</td></tr><tr><td>升级</td><td>提高宝石等级，解锁更强效果。</td></tr><tr><td>共鸣</td><td>当装备上的宝石满足特定组合条件时触发的额外效果。</td></tr><tr><td>gem layer</td><td>写入装备的宝石展示层，由 EmakiGem 自身的状态服务管理。</td></tr></tbody></table><h2 id="默认配置目录" tabindex="-1">默认配置目录 <a class="header-anchor" href="#默认配置目录" aria-label="Permalink to “默认配置目录”">​</a></h2><div class="language-text"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>plugins/EmakiGem/</span></span>
<span class="line"><span>├── config.yml</span></span>
<span class="line"><span>├── conditions/</span></span>
<span class="line"><span>├── gems/</span></span>
<span class="line"><span>├── items/</span></span>
<span class="line"><span>├── resonances/</span></span>
<span class="line"><span>├── gui/</span></span>
<span class="line"><span>│   ├── gem/</span></span>
<span class="line"><span>│   └── open/</span></span>
<span class="line"><span>└── lang/</span></span></code></pre></div><p>目录说明：</p><table tabindex="0"><thead><tr><th>目录</th><th>作用</th></tr></thead><tbody><tr><td><code>gems/</code></td><td>宝石定义。</td></tr><tr><td><code>items/</code></td><td>插槽物品配置（定义哪些装备可拥有插槽）。</td></tr><tr><td><code>resonances/</code></td><td>宝石共鸣定义。</td></tr><tr><td><code>conditions/</code></td><td>镶嵌、开孔、提取、升级条件。</td></tr><tr><td><code>gui/gem/</code></td><td>镶嵌 / 提取 / 升级 / 洗炼 GUI。</td></tr><tr><td><code>gui/open/</code></td><td>开孔 GUI。</td></tr></tbody></table><h2 id="主配置键" tabindex="-1">主配置键 <a class="header-anchor" href="#主配置键" aria-label="Permalink to “主配置键”">​</a></h2><p><code>config.yml</code> 的顶层键：</p><table tabindex="0"><thead><tr><th>键</th><th>默认值</th><th>说明</th></tr></thead><tbody><tr><td><code>version</code></td><td><code>&quot;2.8.0&quot;</code></td><td>配置结构标记，由资源同步流程维护，不是功能开关。</td></tr><tr><td><code>language</code></td><td><code>&quot;zh_CN&quot;</code></td><td>语言文件名，对应 <code>lang/&lt;language&gt;.yml</code>。</td></tr><tr><td><code>release_default_data</code></td><td><code>true</code></td><td>是否在启动时释放内置默认数据（<code>gems/</code>、<code>items/</code>、<code>resonances/</code>）。设为 <code>false</code> 后这三类默认文件不再补齐，但 <code>gui/</code>、<code>conditions/</code>、<code>config.yml</code> 与 <code>lang/*.yml</code> 不受影响。</td></tr><tr><td><code>socket_openers</code></td><td>—</td><td>开孔器定义，见<a href="./socket-openers.html">开孔器系统</a>。</td></tr><tr><td><code>inlay_success</code></td><td>—</td><td>镶嵌成功率，见<a href="./inlay-chance.html">镶嵌成功率</a>。</td></tr><tr><td><code>number_format.default</code></td><td><code>&quot;0.##&quot;</code></td><td>默认数值格式。整节缺失或值为空白时回退为 <code>0.##</code>。</td></tr><tr><td><code>op_bypass</code></td><td><code>false</code></td><td>OP 是否绕过镶嵌、开孔与取出的消耗及条件检查。</td></tr><tr><td><code>reroll.session_ttl_seconds</code></td><td><code>120</code></td><td>洗炼候选会话存活秒数，最小 1；超时后候选作废并退费。变更只影响新生成的候选。</td></tr><tr><td><code>gui.default_mode</code></td><td><code>&quot;inlay&quot;</code></td><td>GUI 服务的默认打开模式。可写 <code>inlay</code>、<code>upgrade</code>、<code>open</code>（别名 <code>open_socket</code>、<code>socket_open</code>）；无法识别的值回退为 <code>inlay</code>。命令仍需显式带模式参数。</td></tr><tr><td><code>gui.save_on_close</code></td><td><code>false</code></td><td>关闭界面时是否保存当前操作状态。</td></tr><tr><td><code>condition</code></td><td>—</td><td>全局条件组配置，缺失时为空条件组、类型 <code>all_of</code>。</td></tr></tbody></table><div class="note custom-block"><p class="custom-block-title custom-block-title-default">NOTE</p><p><code>op_bypass</code> 曾位于 <code>permission.op_bypass</code>。旧键仍可被读取（顶层键优先），启动时会自动迁移到顶层并在控制台留一条提示。</p></div><div class="warning custom-block"><p class="custom-block-title custom-block-title-default">WARNING</p><p><code>version</code> 有两条互不相干的版本线，不要混用：<code>config.yml</code> 中的默认资源值是 <code>2.8.0</code>；源码内部另有迁移常量 <code>CURRENT_VERSION = 2.7.8</code>，仅用于配置迁移比对。两者用途不同。</p></div><h2 id="功能页面" tabindex="-1">功能页面 <a class="header-anchor" href="#功能页面" aria-label="Permalink to “功能页面”">​</a></h2><table tabindex="0"><thead><tr><th>页面</th><th>内容</th></tr></thead><tbody><tr><td><a href="./commands.html">命令与权限</a></td><td>GUI、检查、清理状态、重载和调试命令。</td></tr><tr><td><a href="./gems.html">宝石定义</a></td><td>宝石效果、费用、提取、升级和插槽类型。</td></tr><tr><td><a href="./socket-openers.html">开孔器系统</a></td><td><code>socket_openers</code>、开孔材料、插槽解锁和失败反馈。</td></tr><tr><td><a href="./inlay-chance.html">镶嵌成功率</a></td><td><code>inlay_success</code>、成功率公式和失败处理。</td></tr><tr><td><a href="./resonance.html">宝石共鸣</a></td><td>多宝石组合、共鸣效果和撤销规则。</td></tr><tr><td><a href="./templates.html">GUI 模板</a></td><td>镶嵌、开孔、升级界面配置。</td></tr><tr><td><a href="./extract.html">提取流程</a></td><td>提取费用、返还模式和效果回退。</td></tr><tr><td><a href="./process.html">镶嵌与开孔流程</a></td><td>镶嵌与开孔的执行顺序与校验点。</td></tr><tr><td><a href="./placeholders.html">占位符</a></td><td>PlaceholderAPI 输出。</td></tr><tr><td><a href="./corelib-actions.html">CoreLib 动作</a></td><td>EmakiGem 注册的 CoreLib 动作。</td></tr><tr><td><a href="./api.html">API</a></td><td>运行时集成与外部调用。</td></tr><tr><td><a href="./events.html">事件 API</a></td><td>可监听的 Bukkit 事件。</td></tr></tbody></table><h2 id="典型流程" tabindex="-1">典型流程 <a class="header-anchor" href="#典型流程" aria-label="Permalink to “典型流程”">​</a></h2><h3 id="开孔" tabindex="-1">开孔 <a class="header-anchor" href="#开孔" aria-label="Permalink to “开孔”">​</a></h3><ol><li>玩家打开开孔 GUI。</li><li>放入目标装备。</li><li>检查插槽物品配置、当前已开放插槽、条件和费用。</li><li>成功后解锁新插槽。</li><li>CoreLib 重建装备展示。</li></ol><h3 id="镶嵌" tabindex="-1">镶嵌 <a class="header-anchor" href="#镶嵌" aria-label="Permalink to “镶嵌”">​</a></h3><ol><li>玩家放入目标装备和宝石。</li><li>模块检查插槽类型、宝石 <code>socket_compatibility</code>、数量限制和条件。</li><li>扣除镶嵌费用（<code>inlay_cost</code>）。</li><li>写入宝石状态和效果（属性、技能、名称/Lore 操作）。</li><li>检查并激活满足条件的共鸣。</li><li>重建 gem layer。</li></ol><h3 id="提取" tabindex="-1">提取 <a class="header-anchor" href="#提取" aria-label="Permalink to “提取”">​</a></h3><ol><li>玩家选择要提取的宝石。</li><li>检查费用（<code>extract_cost</code>）、权限和条件。</li><li>成功时按 <code>extract_return</code> 配置返还宝石并清空插槽。</li><li>撤销该宝石的所有效果（通过 ItemOperationLedger 精确回退）。</li><li>重新检查共鸣状态。</li></ol><h3 id="升级" tabindex="-1">升级 <a class="header-anchor" href="#升级" aria-label="Permalink to “升级”">​</a></h3><div class="note custom-block"><p class="custom-block-title custom-block-title-default">NOTE</p><p>升级有独立 GUI 入口：<code>/emakigem gui upgrade</code>，镶嵌界面里也有升级模式按钮。但材料、费用与成功率判定由 <strong>EmakiStrengthen</strong> 的强化配方决定，宝石定义只负责各等级的效果。</p></div><ol><li>读取目标宝石，检查 <code>stages</code> 是否启用、是否已达 <code>max_level</code>、目标等级是否已配置。</li><li>检查 EmakiStrengthen 是否可用，把材料与费用交给对应强化配方结算。</li><li>成功后提升宝石等级，应用新等级的 effects。</li><li>失败时按该强化配方的规则处理。</li></ol><h3 id="洗炼" tabindex="-1">洗炼 <a class="header-anchor" href="#洗炼" aria-label="Permalink to “洗炼”">​</a></h3><ol><li>玩家手持宝石，通过命令或界面按钮生成洗炼候选。</li><li>校验宝石 <code>reroll</code> 是否启用、词缀池是否可用，然后立即扣费并开启候选会话。</li><li>确认时校验配置指纹与物品实例，通过后把候选词缀写入主手宝石。</li><li>超时、取消或校验失败时作废候选并退费。</li></ol><h3 id="共鸣激活" tabindex="-1">共鸣激活 <a class="header-anchor" href="#共鸣激活" aria-label="Permalink to “共鸣激活”">​</a></h3><ol><li>镶嵌或提取宝石后，系统自动检查所有共鸣定义。</li><li>按 <code>chain.mode</code> 和 <code>chain.pattern</code> 匹配当前装备上的宝石组合。</li><li>满足条件时激活共鸣，应用 <code>effects</code> 并执行 <code>actions</code>。</li><li>宝石被提取导致不再满足条件时，自动撤销共鸣效果。</li></ol>`,31)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};